// swift-tools-version: 6.4
//
//  Package.swift — `CHTTPBoringSSL` (the vendored BoringSSL oracle, a LOCAL subpackage)
//
//  Phase 3d moved the vendored, symbol-prefixed (`CHTTPBoringSSL_*`) BoringSSL tree — and its
//  hand-written macro-wrapper shim — out of the root package into this local subpackage, for one
//  load-bearing reason: SwiftPM builds EVERY declared root-package target on `swift build`, but
//  builds a DEPENDENCY package's targets only when a consumed product needs them. Keeping the
//  399-file C/C++/asm tree here means:
//
//    • `HTTP_PORTABLE_TLS=1 swift build` (the portable backbone on the pure-Swift HTTPTLS engine)
//      never compiles a single BoringSSL file — the library graph has no edge to this package's
//      products, so they are never scheduled.
//    • `HTTP_PORTABLE_TLS=1 swift test` still gets `CHTTPBoringSSLShims` for the transport test
//      target, which drives the loopback suites with a raw BoringSSL CLIENT — the independent
//      oracle this package deliberately does not rewrite in terms of the engine under test.
//    • `HTTP_BORINGSSL_TLS=1` (the TEMPORARY Phase 3d A/B gate) links the root `HTTPTransport`
//      against both products, exactly as before the move.
//
//  The whole package is deleted in Phase 3e, together with the legacy engine files and the
//  `HTTP_BORINGSSL_TLS` gate, once the interop matrix holds on the HTTPTLS engine.
//
//  Regenerated by `scripts/vendor-boringssl.sh`; see `Sources/CHTTPBoringSSL/NOTICE.txt`.
//

import PackageDescription

let package = Package(
    name: "CHTTPBoringSSL",
    products: [
        .library(name: "CHTTPBoringSSL", targets: ["CHTTPBoringSSL"]),
        .library(name: "CHTTPBoringSSLShims", targets: ["CHTTPBoringSSLShims"])
    ],
    targets: [
        // The vendored module — no system OpenSSL, no `HTTP_OPENSSL_PREFIX` (ADR 0004 Phase 6).
        // The C/C++/asm sources compile in-tree; SwiftPM links libc++ for the C++ `.cc`.
        .target(
            name: "CHTTPBoringSSL",
            path: "Sources/CHTTPBoringSSL",
            cSettings: [
                .define("_GNU_SOURCE"),
                .define("_POSIX_C_SOURCE", to: "200112L"),
                .define("_DARWIN_C_SOURCE")
            ]
        ),
        // The hand-written macro-wrapper shim — the only place that includes the BoringSSL
        // umbrella and holds the unsafe interop.
        .target(
            name: "CHTTPBoringSSLShims",
            dependencies: ["CHTTPBoringSSL"],
            path: "Sources/CHTTPBoringSSLShims",
            cSettings: [.define("_GNU_SOURCE")]
        )
    ],
    // The vendored BoringSSL is C++; pin the standard for its `.cc` sources.
    cxxLanguageStandard: .cxx17
)
